/**
 * 🛡️ P1-D（2026-11-17 · `mc-max-1794845355582-f3d7f352` 实锤）：**段标题占位名治理**。
 *
 * 病灶：真值节点 `43:4892` 的图层名是 `Frame 2136639911`（Figma 自动生成），
 *   vision 直接把它当段标题输出 ⇒ 产物
 *   `<span class="c-device-fg-header-434892-title">Frame 2136639911</span>` 直出到 UI。
 *   真值核对：该段子树只有 3 张统计卡（总设备 8 / 运行中 2 / 离线 1）**本来没有标题**
 *   ⇒ 正确行为是**不渲染段头**，而不是渲染英文图层名。
 *
 * 判据**单一来源**：`isAutoGeneratedNodeName`（`utils/decor-leaf-truth.js`，
 *   与 `isNonSemanticName` 共用 `AUTO_NUMBER_NAME_RX`）。本模块只负责
 *   「取值口径」与「就地净化」，**不另写正则**。
 *
 * 为什么不用 `isNonSemanticName`：它是**节点名**判据（用途 = 覆盖率统计排除），
 *   连 `text` / `label` / `btn` / `tab` 都算无语义 —— 这些词作为**节点名**确实无语义，
 *   但作为 **UI 文本**完全可能是真实文案。本模块只拒「类型词 + 编号」，不拒它们。
 */
import { isAutoGeneratedNodeName } from './decor-leaf-truth.js';

/**
 * 段标题取值**唯一口径**。
 *
 * 顺序与既有 `sec.header?.title || sec.title || sec.name || ''` **逐字一致**，
 * 只是逐个过滤占位名。全为占位名/空 ⇒ 返回 `''`
 * （下游 `resolveSectionHeaderFacts` 见空标题即直接返回 null ⇒ 不渲染段头）。
 *
 * @param {object} sec section（可含 header.title / title / name）
 * @returns {string} 非占位的首个候选；无则空串
 */
export function pickSectionTitle(sec) {
  const cands = [
    sec?.header && typeof sec.header === 'object' ? sec.header.title : undefined,
    sec?.title,
    sec?.name,
  ];
  for (const c of cands) {
    const v = String(c == null ? '' : c).trim();
    if (!v) continue;
    if (isAutoGeneratedNodeName(v)) continue;
    return v;
  }
  return '';
}

/**
 * 设计稿叠字废稿层**真值级去重**（2026-11-17 · `mc-max-1794874512632-3c86927e` 实锤）。
 *
 * 病灶链（监测预警 73:3）：设计稿标题区三层堆叠——
 *   `1:470 标题 GROUP` > [`1:471 GROUP`(含 `1:472`+`1:473` 两条**同 bbox 同文本**
 *   的 TEXT「小标题」)（底）, `1:474 白字 GROUP`(含 `1:475` TEXT「监测预警」)（顶）]。
 *   「小标题」层是被白字层**盖住的废稿层**（设计源文件里改稿留下的占位残层）。
 *   上游 `header-slot-validator#deriveHeaderSlotsFromFigma` 的 `collectTexts` 把
 *   三层全收 ⇒「小标题 小标题」被推导成 `header-right/label` 契约 ⇒ tab 栏被错误
 *   安进面板标题条（真值里 tab 在内容区 y=173）⇒ 与面板标题 bbox 相交 ⇒
 *   RUNTIME-016 反复报（D2 回灌 3 轮不收敛——契约来自真值，LLM 改了也拉回）。
 *
 * 判据（纯几何+文本，命名无关、可辩驳）：
 *   ① **同位叠字**：同一父容器内两条 TEXT，bbox 交叠面积 / 较小者面积 ≥ 0.8 且
 *      characters 去空白后相等 ⇒ 二者是同一文案的两层，保留**源序靠后者**（上层可见），
 *      下层标记 `_dupShadow: true`（消费者跳过）。
 *   ② **被标题覆盖的隐藏层**：TEXT bbox 与**其他** TEXT（非兄弟同文）重叠 ≥ 0.8、
 *      源序在其之前（被盖）、且自身文本不等于任何已物化兄弟文本 ⇒ 同为废稿层。
 *   只标记不删除（单一事实源不变更真值树；消费方 `collectTexts` 类遍历跳过标记节点）。
 *
 * @param {object} figmaRoot Figma 真值树根（{document}|{nodes}|裸树）
 * @returns {{evaluated:number, marked:number, markedIds:string[], markedTexts:string[]}}
 */
export function markDuplicateShadowTexts(figmaRoot) {
  const stats = { evaluated: 0, marked: 0, markedIds: [], markedTexts: [] };
  if (!figmaRoot || typeof figmaRoot !== 'object') return stats;
  const norm = (s) => String(s == null ? '' : s).replace(/\s+/g, '');
  // 🛡️ 注释语义豁免（与 header-slot-validator#isAnnotation 同口径）：`*`/`#` 开头、
  //   TODO/FIXME/标注/备注 是**设计师标注**（常浮在任何元素上方），不是内容层，
  //   不参与「被覆盖废稿」判定（真机夹具 2:7967「*数据实时更新」浮在 tab 文字上
  //   属正常标注形态，0.74 重叠 ⇒ 若不豁免会把 tab 文本误标成废稿）。
  const isAnnotationText = (s) =>
    /^[*#]/.test(String(s || '').trim()) || /TODO|FIXME|标注|备注/.test(String(s || ''));
  // 归一根（与 unwrapFigmaRoot 同族口径，但不引入依赖——就地三分支）
  let root = figmaRoot;
  if (Array.isArray(figmaRoot.children)) root = figmaRoot;
  else if (figmaRoot.document && typeof figmaRoot.document === 'object') root = figmaRoot.document;
  else if (figmaRoot.nodes && typeof figmaRoot.nodes === 'object') {
    const first = Object.values(figmaRoot.nodes)[0];
    if (first && typeof first === 'object') root = first.document || first;
  }

  const overlapRatio = (a, b) => {
    if (!a || !b) return 0;
    const ix = Math.max(0, Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x));
    const iy = Math.max(0, Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y));
    const inter = ix * iy;
    const aA = (a.width || 0) * (a.height || 0);
    const bA = (b.width || 0) * (b.height || 0);
    const smaller = Math.min(aA, bA);
    return smaller > 0 ? inter / smaller : 0;
  };

  const walk = (node) => {
    if (!node || typeof node !== 'object') return;
    const kids = Array.isArray(node.children) ? node.children : [];
    const texts = kids.filter(
      (c) => c && c.type === 'TEXT' && typeof c.characters === 'string' && norm(c.characters),
    );
    if (texts.length >= 2) {
      stats.evaluated += texts.length;
      // ① 同位叠字：两两比对（源序靠后者为可见层）
      for (let i = 0; i < texts.length; i++) {
        for (let j = i + 1; j < texts.length; j++) {
          const a = texts[i];
          const b = texts[j];
          if (a._dupShadow || b._dupShadow) continue;
          if (norm(a.characters) !== norm(b.characters)) continue;
          if (overlapRatio(a.absoluteBoundingBox, b.absoluteBoundingBox) >= 0.8) {
            // i 源序在前 = 底层废稿；j 在后 = 可见层
            a._dupShadow = true;
            stats.marked += 1;
            if (stats.markedIds.length < 12) {
              stats.markedIds.push(String(a.id ?? ''));
              stats.markedTexts.push(norm(a.characters).slice(0, 16));
            }
          }
        }
      }
      // ② 被标题覆盖的隐藏层：与「其他文本」重叠 ≥0.8、源序更早、文本不同
      for (let i = 0; i < texts.length; i++) {
        const a = texts[i];
        if (a._dupShadow) continue;
        for (let j = 0; j < texts.length; j++) {
          if (i === j) continue;
          const b = texts[j];
          const aLater = kids.indexOf(a) > kids.indexOf(b);
          if (aLater) continue; // a 在上层可见，不是废稿
          if (norm(a.characters) === norm(b.characters)) continue;
          if (overlapRatio(a.absoluteBoundingBox, b.absoluteBoundingBox) >= 0.8) {
            a._dupShadow = true;
            stats.marked += 1;
            if (stats.markedIds.length < 12) {
              stats.markedIds.push(String(a.id ?? ''));
              stats.markedTexts.push(norm(a.characters).slice(0, 16));
            }
            break;
          }
        }
      }
    }
    for (const c of kids) walk(c);
  };
  walk(root);
  // 🛡️ 2026-11-17 三轮补（836f1e17 实锤）：**跨 GROUP 的覆盖链**。真机形态：
  //   标题 FRAME > [1:471(小标题×2), 1:474(白字>监测预警)]——小标题层整组在白字组
  //   **之前**（被盖），同父兄弟比对只见 GROUP 不见 TEXT ⇒ 组间覆盖关系漏标 ⇒
  //   可见侧那条「小标题」(1:473) 仍被采集 ⇒ headerSlots 契约仍含「小标题」。
  //   补：收集**子树全部 TEXT**（扁平化带深度），凡与「更晚渲染的不同文本 TEXT」
  //   重叠 ≥0.8 且自身更早渲染 ⇒ 标记废稿。渲染序判定（产物树无 clip/独立堆叠
  //   上下文，与渲染事实一致）：深度更浅者先渲染；同深度按同父源序。
  const allTexts = [];
  const collectFlat = (n, depth) => {
    if (!n || typeof n !== 'object') return;
    if (
      n.type === 'TEXT' &&
      typeof n.characters === 'string' &&
      norm(n.characters) &&
      !isAnnotationText(n.characters)
    ) {
      allTexts.push({ node: n, depth });
    }
    for (const c of n.children || []) {
      c.__dupParent = n;
      collectFlat(c, depth + 1);
    }
  };
  collectFlat(root, 0);
  const renderOrderOf = (entry) => {
    // 渲染序 = 祖先链按「父在子前」展开后的全局位置。简化为：
    //   深度浅者先；同深度时比「各自父链上最近公共祖先下的源序」——实现上取
    //   entry.node 在其父 children 的 index 拼路径。用路径字典序即可稳定比较。
    const path = [];
    let cur = entry.node;
    while (cur) {
      const p = cur.__dupParent;
      if (!p) break;
      const idx = (p.children || []).indexOf(cur);
      path.unshift(idx);
      cur = p;
    }
    return path;
  };
  const cmpPath = (p1, p2) => {
    for (let k = 0; k < Math.min(p1.length, p2.length); k++) {
      if (p1[k] !== p2[k]) return p1[k] - p2[k];
    }
    return p1.length - p2.length;
  };
  const orderCache = new Map();
  for (const e of allTexts) orderCache.set(e.node, renderOrderOf(e));
  for (const { node: a } of allTexts) {
    if (a._dupShadow) continue;
    for (const { node: b } of allTexts) {
      if (a === b) continue;
      if (norm(a.characters) === norm(b.characters)) continue;
      // 🛡️ 2026-11-17 四轮校准（插桩实测）：跨组覆盖链的重叠比实际 0.72（473 与 475
      //   bbox 差 1.6px 偏移 + 高度差 5px ⇒ 交叠/较小者 = 2112/2952）。同位叠字判据
      //   保持 ≥0.8（严格同形），跨组覆盖放宽到 **≥0.7**——语义不同（这里是「整组
      //   被上层文本盖住」，覆盖面积天然略小），且要求源序更早 + 文本不同双前置。
      //   真机 472(0.72 触发标记)、473(0.72) 双双命中，475(最后渲染) 不受影响。
      if (cmpPath(orderCache.get(a), orderCache.get(b)) >= 0) continue; // a 不早于 b
      const ovlCross = overlapRatio(a.absoluteBoundingBox, b.absoluteBoundingBox);
      if (ovlCross >= 0.7) {
        a._dupShadow = true;
        stats.marked += 1;
        if (stats.markedIds.length < 12) {
          stats.markedIds.push(String(a.id ?? ''));
          stats.markedTexts.push(norm(a.characters).slice(0, 16));
        }
        break;
      }
    }
  }
  // 清理辅助引用（不污染真值树）
  for (const { node: n } of allTexts) delete n.__dupParent;
  // 清理深层辅助引用（collectFlat 遍历过的所有节点）
  const cleanup = (n) => {
    if (!n || typeof n !== 'object') return;
    if ('__dupParent' in n) delete n.__dupParent;
    for (const c of n.children || []) cleanup(c);
  };
  cleanup(root);
  return stats;
}

/**
 * 段标题占位名**就地净化**（planner 出口唯一位置 —— 覆盖所有上游来源与所有后置 pass）。
 *
 * 为什么在 planner 出口而不是渲染层：`effectiveSections` 是所有下游
 *   （`collectLeafSections` / takeover / prompt / `renderFoldedGridLeafVue` / 验收 D1·C1b）
 *   的**唯一入参**。在出口净化一次 ⇒ 全链路受益；放在 `applySectionHeader` 只是治标
 *   （别的消费者仍看到占位名）。
 *
 * 只清 `header.title` 与 `title` 两个 **UI 文本**字段，**不动 `name`**：
 *   `name` 是节点名，下游（`visual-parser` 等）按 name 匹配 Figma 节点，清掉会破坏锚定。
 *
 * 纯函数（就地改写入参数组元素 + 返回计数），幂等，fail-open（非数组 ⇒ 零计数）。
 *
 * @param {Array} sections
 * @returns {{evaluated:number, cleared:number, clearedIds:string[], clearedValues:string[]}}
 */
export function sanitizeSectionTitlePlaceholders(sections) {
  const stats = { evaluated: 0, cleared: 0, clearedIds: [], clearedValues: [] };
  if (!Array.isArray(sections)) return stats;
  for (const sec of sections) {
    if (!sec || typeof sec !== 'object') continue;
    stats.evaluated += 1;
    let hit = null;
    if (sec.header && typeof sec.header === 'object') {
      const ht = String(sec.header.title == null ? '' : sec.header.title).trim();
      if (ht && isAutoGeneratedNodeName(ht)) {
        sec.header.title = '';
        hit = ht;
      }
    }
    const st = String(sec.title == null ? '' : sec.title).trim();
    if (st && isAutoGeneratedNodeName(st)) {
      sec.title = '';
      if (!hit) hit = st;
    }
    if (hit) {
      stats.cleared += 1;
      if (stats.clearedIds.length < 12) {
        stats.clearedIds.push(String(sec.id ?? ''));
        stats.clearedValues.push(hit);
      }
    }
  }
  return stats;
}
